import {zipSync} from './vendor/formats.js';
import {pngResolution} from './png-resolution.js?v=20261025-release1';
import {printRegion,pageRole,comicGuides,mmToPx} from './comic-format.js?v=20261025-release1';
import {pageLabel} from './publication-model.js?v=20261025-release1';
const encode=s=>new TextEncoder().encode(s);
// Lossless RGB image pages; byte offsets include binary streams, not JS character counts.
export function rasterPDF(pages){
 const chunks=[encode('%PDF-1.4\n%SCROLL\n')],offsets=[0];let length=chunks[0].length;
 const add=data=>{const bytes=typeof data==='string'?encode(data):data;chunks.push(bytes);length+=bytes.length;};
 const object=(id,body,stream)=>{offsets[id]=length;add(`${id} 0 obj\n${body}`);if(stream){add('\nstream\n');add(stream);add('\nendstream');}add('\nendobj\n');};
 object(1,'<< /Type /Catalog /Pages 2 0 R >>');object(2,`<< /Type /Pages /Count ${pages.length} /Kids [${pages.map((_,i)=>`${3+i*3} 0 R`).join(' ')}] >>`);
 pages.forEach((p,i)=>{const id=3+i*3,w=p.widthMm*72/25.4,h=p.heightMm*72/25.4,content=encode(`q ${w.toFixed(6)} 0 0 ${h.toFixed(6)} 0 0 cm /Im0 Do Q`);object(id,`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${w.toFixed(6)} ${h.toFixed(6)}] /Resources << /XObject << /Im0 ${id+1} 0 R >> >> /Contents ${id+2} 0 R >>`);object(id+1,`<< /Type /XObject /Subtype /Image /Width ${p.width} /Height ${p.height} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /FlateDecode /Length ${p.bytes.length} >>`,p.bytes);object(id+2,`<< /Length ${content.length} >>`,content);});
 const start=length;add(`xref\n0 ${offsets.length}\n0000000000 65535 f \n`);for(const offset of offsets.slice(1))add(`${String(offset).padStart(10,'0')} 00000 n \n`);add(`trailer\n<< /Size ${offsets.length} /Root 1 0 R >>\nstartxref\n${start}\n%%EOF\n`);return new Blob(chunks,{type:'application/pdf'});
}
async function rgbBytes(cv){const data=cv.getContext('2d').getImageData(0,0,cv.width,cv.height).data,rgb=new Uint8Array(cv.width*cv.height*3);for(let s=0,d=0;s<data.length;s+=4){rgb[d++]=data[s];rgb[d++]=data[s+1];rgb[d++]=data[s+2];}return new Uint8Array(await new Response(new Blob([rgb]).stream().pipeThrough(new CompressionStream('deflate'))).arrayBuffer());}
export function cropMarks(ctx,p,pg,scale){
 const trim=comicGuides(p,pg)[1],b=p.comic.bleedMm*p.width/p.comic.paperWidthMm,gap=1*p.dpi/25.4,len=4*p.dpi/25.4;ctx.save();ctx.scale(scale,scale);ctx.strokeStyle='#000';ctx.lineWidth=.2*p.dpi/25.4;ctx.beginPath();
 for(const [x,dx]of [[trim.x,-1],[trim.x+trim.w,1]])for(const [y,dy]of [[trim.y,-1],[trim.y+trim.h,1]]){ctx.moveTo(x+dx*(b+gap),y);ctx.lineTo(x+dx*(b+gap+len),y);ctx.moveTo(x,y+dy*(b+gap));ctx.lineTo(x,y+dy*(b+gap+len));}ctx.stroke();ctx.restore();
}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}
export function setupPrintOutput(root,api){
 if(root.dataset.running==='true')return;
 const p=api.getProject();if(p.format!=='comic'){root.textContent='웹툰은 상단 내보내기에서 PNG·PSD를 출력하세요. 인쇄 출력은 출판만화 원고에서 사용합니다.';return;}
 root.innerHTML=`<form id="printOutputForm"><div class="print-field-grid"><label>페이지 범위<select id="printScope"><option value="body">본문만</option><option value="all">전체 페이지</option><option value="covers">표지 4면</option><option value="selected">페이지 목록에서 선택한 면</option><option value="range">번호 범위</option></select></label><label>페이지 번호 · 예: 1-4,7<input id="printPageRange" placeholder="1-4,7" disabled></label><label>출력 영역<select id="printCrop"><option value="trim">재단 후 크기</option><option value="bleed">재단 + 사방 도련</option><option value="kdp">KDP 본문 · 위/아래/바깥 3.175mm</option><option value="paper">원고 용지 전체</option></select></label><label>형식<select id="printFileType"><option value="pdf">인쇄 PDF · RGB 무손실 래스터</option><option value="png">페이지별 PNG · ZIP</option></select></label><label>출력 색상<select id="printColor"><option value="color">컬러 · RGB</option><option value="gray">흑백 · 회색조</option></select></label><label>출력 해상도<select id="printDpi"><option value="300">300dpi</option>${p.dpi===600?'<option value="600">600dpi · 원본</option>':''}${p.dpi<300?`<option value="${p.dpi}">${p.dpi}dpi · 원본</option>`:''}</select></label><label class="check"><input id="printMarks" type="checkbox" disabled>용지 바깥에 재단 표시</label></div><p id="printDimensions"></p><p class="publication-help">안내선은 출력하지 않습니다. 켜 둔 쪽 번호는 출력합니다. PDF는 페이지 순서대로 한 면씩 저장하며 글자는 이미지에 포함됩니다. CMYK·ICC 교정이나 접지용 면 배치는 지원하지 않습니다.</p><button type="submit" class="primary">인쇄 파일 만들기</button><button type="button" id="printCancel" hidden>작업 취소</button><div id="printProgress" role="status"></div></form>`;
 const $=id=>root.querySelector('#'+id),form=$('printOutputForm');if(p.dpi<300)$('printDpi').value=p.dpi;let canceled=false,running=false;
 function chosen(){const scope=$('printScope').value;if(scope==='range'){const ids=new Set();for(const term of $('printPageRange').value.split(',')){const m=term.trim().match(/^(\d+)(?:\s*-\s*(\d+))?$/);if(!m)throw Error('페이지 범위를 1-4,7 형식으로 입력하세요.');const a=+m[1],b=+(m[2]||m[1]);if(a<1||b<a||b>p.pages.length)throw Error('페이지 번호 범위를 확인하세요.');for(let i=a;i<=b;i++)ids.add(i-1);}return p.pages.filter((_,i)=>ids.has(i));}return p.pages.filter(pg=>scope==='all'||scope==='body'&&pageRole(pg)==='body'||scope==='covers'&&pageRole(pg)!=='body'||scope==='selected'&&api.selected().includes(pg.id));}
 function summary(){const mode=$('printCrop').value;$('printPageRange').disabled=$('printScope').value!=='range';$('printMarks').disabled=mode!=='paper';if(mode!=='paper')$('printMarks').checked=false;try{const pages=chosen(),r=printRegion(p,pages[0],mode);$('printDimensions').textContent=`${pages.length}면 · ${r.widthMm.toFixed(3)} × ${r.heightMm.toFixed(3)}mm · ${mmToPx(r.widthMm,+$('printDpi').value)} × ${mmToPx(r.heightMm,+$('printDpi').value)}px`;}catch(e){$('printDimensions').textContent=e.message;}}
 form.addEventListener('input',summary);summary();$('printCancel').onclick=()=>{canceled=true;$('printProgress').textContent='현재 페이지 처리 후 취소합니다…';};
 form.onsubmit=async e=>{e.preventDefault();if(running)return;const controls=[...form.querySelectorAll('input,select,button[type=submit]')];try{const pages=chosen(),mode=$('printCrop').value,dpi=+$('printDpi').value,pdf=$('printFileType').value==='pdf',marks=$('printMarks').checked,gray=$('printColor').value==='gray';if(!pages.length)throw Error('출력할 페이지가 없습니다.');if(mode==='kdp'&&pages.some(pg=>pageRole(pg)!=='body'))throw Error('KDP 본문은 본문 페이지만 선택하세요. 표지는 별도 사양으로 출력합니다.');const regions=pages.map(pg=>printRegion(p,pg,mode));if(marks){const c=p.comic,room=Math.min((c.paperWidthMm-c.trimWidthMm)/2,(c.paperHeightMm-c.trimHeightMm)/2);if(room<c.bleedMm+5)throw Error('재단 표시에는 도련 바깥으로 5mm 이상의 용지 여유가 필요합니다.');}running=true;root.dataset.running='true';canceled=false;controls.forEach(el=>el.disabled=true);$('printCancel').hidden=false;
   await document.fonts.ready;const images=[],files={};
   for(let i=0;i<pages.length;i++){if(!root.closest('dialog')?.open)canceled=true;if(canceled)break;const pg=pages[i],r=regions[i];$('printProgress').textContent=`${i+1} / ${pages.length}면 · ${pageLabel(p,pg)} 출력 중…`;await new Promise(requestAnimationFrame);let cv=await api.renderPage(pg,Math.max(r.w,r.h)*dpi/p.dpi,mode);const tw=mmToPx(r.widthMm,dpi),th=mmToPx(r.heightMm,dpi);if(cv.width!==tw||cv.height!==th){const exact=document.createElement('canvas');exact.width=tw;exact.height=th;exact.getContext('2d').drawImage(cv,0,0,tw,th);cv.width=1;cv=exact;}try{if(gray){const ctx=cv.getContext('2d'),image=ctx.getImageData(0,0,cv.width,cv.height),d=image.data;for(let k=0;k<d.length;k+=4){const v=Math.round(.2126*d[k]+.7152*d[k+1]+.0722*d[k+2]);d[k]=d[k+1]=d[k+2]=v;}ctx.putImageData(image,0,0);}if(marks)cropMarks(cv.getContext('2d'),p,pg,cv.width/r.w);if(pdf)images.push({bytes:await rgbBytes(cv),width:cv.width,height:cv.height,widthMm:r.widthMm,heightMm:r.heightMm});else{const blob=await new Promise(resolve=>cv.toBlob(resolve,'image/png'));files[`${String(p.pages.indexOf(pg)+1).padStart(3,'0')}.png`]=pngResolution(new Uint8Array(await blob.arrayBuffer()),dpi);}}finally{cv.width=1;}}
   if(!root.closest('dialog')?.open)canceled=true;if(canceled){$('printProgress').textContent='취소했습니다. 원고는 변경되지 않았습니다.';return;}const name=(p.title||'원고').replace(/[\\/:*?"<>|]/g,'_');download(pdf?rasterPDF(images):new Blob([zipSync(files,{level:0})]),name+'-인쇄.'+(pdf?'pdf':'zip'));$('printProgress').textContent=`완료 · ${pages.length}면을 저장했습니다.`;
  }catch(e){$('printProgress').textContent=e.message;}finally{running=false;delete root.dataset.running;controls.forEach(el=>el.disabled=false);$('printCancel').hidden=true;summary();}};
}
